class Rectangle {
  constructor(protected w: number, protected h: number) {}
  setWidth(w: number) { this.w = w; }   // @post height is unchanged
  setHeight(h: number) { this.h = h; }  // @post width is unchanged
  area() { return this.w * this.h; }
}

// 'A square is a rectangle', so extend it.
class Square extends Rectangle {
  setWidth(w: number) { this.w = w; this.h = w; }   // also mutates height
  setHeight(h: number) { this.w = h; this.h = h; }  // also mutates width
}

// caller written against Rectangle's contract:
function grow(r: Rectangle) {
  r.setWidth(5);
  r.setHeight(4);
  return r.area();   // a caller expects 5 * 4 = 20
}
